outcome.final_sql:
WITH cte_final AS (
    SELECT COUNT(*) AS answer
    FROM users
    WHERE LastAccessDate > '2014-09-01'
)
SELECT * FROM cte_final;

WITH final_answer AS (
    SELECT 
        (SELECT SUM(p.ViewCount) FROM users u INNER JOIN posts p ON u.Id = p.OwnerUserId WHERE u.DisplayName = 'Mornington') - 
        (SELECT SUM(p.ViewCount) FROM users u INNER JOIN posts p ON u.Id = p.OwnerUserId WHERE u.DisplayName = 'Amos') AS view_count_difference
)
SELECT view_count_difference FROM final_answer;

SELECT DISTINCT type
FROM event
WHERE location = 'MU 215';

WITH highest_monthly_consumption_2012 AS (
    SELECT MAX(Consumption) AS answer
    FROM yearmonth
    WHERE SUBSTR(Date, 1, 4) = '2012'
)
SELECT * FROM highest_monthly_consumption_2012;
